MM.mnemo[15] = {"cards":[{"id":"ko-k3-0277","w":"그러면","cs":"v tom případě; tedy; pak","en":"in that case, if so, then","p":"o","o":"k","ex":"그러면 이거는 뭐예요?","exc":"Co je v tom případě tohle? (는 → téma)","m":"Spojka vzniklá ze slovesa 그렇다 (být takový) + koncovka -(으)면 (když, jestli) = ‚když je to tak, v tom případě‘. V hovoru se často zkracuje na 그럼."},{"id":"ko-k3-0278","w":"그럼","cs":"tedy; pak; tak (zkratka z 그러면)","en":"then (short for 그러면)","p":"o","o":"k","ex":"그럼 이거는 어때요?","exc":"Tak co říkáš na tohle? (는 → téma)","m":"Běžná hovorová zkratka spojky 그러면 (v tom případě, tedy). Stojí na začátku věty jako reakce na předchozí situaci."},{"id":"ko-k3-0279","w":"그럼요","cs":"samozřejmě; ovšem; jistě","en":"of course!","p":"f","o":"k","ex":"그럼요!","exc":"Samozřejmě!","m":"Zdvořilé citoslovce pro silný souhlas (vzniklo ze spojky 그럼 + zdvořilostní 요). V hovoru bez 요 zní 그럼 (Ovšem!)."},{"id":"ko-k3-0280","w":"만약","cs":"kdyby; jestliže; v případě, že","en":"if, in case","p":"o","o":"s","ex":"만약 -(으)면","exc":"kdyby…; jestliže… (-(으)면 → když, jestli)","m":"萬 deset tisíc (všechny možnosti) + 若 jako, kdyby = ‚kdyby náhodou, v případě, že‘. Stojí na začátku podmínkové věty a ladí s koncovkou -(으)면 na konci.","r":["man-萬","yak-若"]},{"id":"ko-k3-0281","w":"이제","cs":"teď; nyní; odteď","en":"now (from now on)","p":"o","o":"k","ex":"그럼 저는 이제 갈게요.","exc":"Tak já už teď půjdu. (는 → téma; -ㄹ게요 → udělám)","m":"Vyjadřuje ‚teď‘ s důrazem na změnu situace nebo přechod k novému ději (‚odteď, už‘). Tím se liší od 지금 (právě teď v tuto chvíli)."},{"id":"ko-k3-0282","w":"어떻게","cs":"jak; jakým způsobem","en":"how","p":"o","o":"k","ex":"그럼 이제 어떻게 해요?","exc":"Co teď tedy budeme dělat? (doslova ‚Jak to teď uděláme?‘)","m":"Výslovnost [어떠케]. Příslovce od 어떻다 (jaký). Pozor na záměnu se stejným zvukem 어떡해 (zkratka z 어떻게 해 = ‚Co mám dělat?!‘)."},{"id":"ko-k3-0283","w":"김밥","cs":"kimbap (korejská rýžová rolka v mořské řase)","en":"kimbap","p":"n","o":"k","ex":"한국 음식 좋아해요? 그럼 김밥도 좋아해요?","exc":"Máš rád korejské jídlo? A máš tedy rád i kimbap? (도 → také, i)","m":"Složené z 김 (sušená mořská řasa) + 밥 (vařená rýže) = rýže se zeleninou, vejcem či masem zabalená v řase. Výslovnost [김밥] i [김빱], obojí je správně."},{"id":"ko-k3-0284","w":"우체국","cs":"pošta (poštovní úřad)","en":"post office","p":"n","o":"s","ex":"우체국 옆에 냉면 맛있는 집 있는 거 알아요?","exc":"Víš, že vedle pošty je dobrá restaurace na studené nudle? (에 → kde; -는 → přívlastek)","m":"郵 pošta + 遞 doručovat + 局 úřad = úřad pro doručování pošty, tedy pošta. 局 jako v 방송국 (vysílací stanice) nebo 약국 (lékárna).","r":["u-郵","che-遞","guk-局"]},{"id":"ko-k3-0285","w":"냉면","cs":"studené nudle (tradiční korejské jídlo)","en":"cold noodles","p":"n","o":"s","ex":"우체국 옆에 냉면 맛있는 집 있는 거 알아요?","exc":"Víš, že vedle pošty je dobrá restaurace na studené nudle? (에 → kde; -는 → přívlastek)","m":"冷 studený + 麵 nudle = studené pohankové nudle podávané v ledovém vývaru nebo s pikantní omáčkou. 冷 jako v 냉장고 (lednička).","r":["naeng-冷","myeon-麵"]},{"id":"ko-k3-0287","w":"택시","cs":"taxík; taxi","en":"taxi","p":"n","o":"e","ex":"그러면 택시 타세요.","exc":"V tom případě si vezměte taxík.","m":"Výpůjčka z anglického taxi. Jet taxíkem se korejsky řekne 택시를 타다 (doslova ‚nastoupit na taxi‘), zavolat si ho pak 택시를 부르다."},{"id":"ko-k3-0288","w":"혼자","cs":"sám; o samotě","en":"alone","p":"o","o":"k","ex":"그러면 혼자 먹고 올게요.","exc":"V tom případě se najím sám a přijdu. (-고 → a pak; -ㄹ게요 → udělám)","m":"Používá se samostatně jako příslovce (혼자 먹다 = jíst sám, 혼자 살다 = bydlet sám). Dnes oblíbené zkratky: 혼밥 (jíst sám) a 혼술 (pít alkohol sám)."}],"gram":{"id":"ko-k3-g15","w":"그러면, 그럼","en":"Well then, In that case, If so","cs":"tak teda, v tom případě, jestli je to tak","vy":"Spojka 그러면 (v běžné mluvené řeči zkráceně 그럼) stojí na začátku věty a navazuje na to, co právě řekl druhý člověk nebo co vyplynulo ze situace (‚tak teda…, v tom případě…, jestli je to tak…‘). Vznikla ze slovesa 그렇다 (být takový) a podmínkové koncovky -면 (když). Samostatné zvolání 그럼요! znamená nadšený souhlas ‚samozřejmě!, no ovšem!‘.","m":"Neplést zkrácené 그럼 (tak teda, v tom případě) s přívlastkem 그런 (takový, např. 그런 사람 = takový člověk). Jako samostatná odpověď 그럼요! znamená ‚Samozřejmě!‘.","s":[["그러면","v tom případě; jestli je to tak; tak teda (그렇다 + -면)"],["그럼","hovorová zkrácená podoba výrazu 그러면 (neplést s 그런 = takový)"],["그럼요!","Samozřejmě! / No ovšem! (zdvořilé zvolání)"],["그러면 이거는 뭐예요?","A co je teda tohle?"],["지금 바빠요? 그러면 언제 안 바빠요?","Máš teď napilno? Tak kdy nemáš napilno?"],["한국 음식 좋아해요? 그럼 김밥도 좋아해요?","Máš rád korejské jídlo? Tak to máš rád i kimbap?"],["진짜요? 그럼 이제 어떻게 해요?","Vážně? Tak co budeme dělat teď?"],["그럼 이거는 어때요?","Tak co říkáš na tohle?"],["우체국 옆에 냉면 맛있는 집 있는 거 알아요?","Víš, že vedle pošty je dobrá restaurace se studenými nudlemi?"],["그럼 오늘 점심 거기서 먹을까요?","Tak si tam dneska dáme oběd?"],["그러면 택시 타세요.","V tom případě si vezměte taxík."],["그러면 창문 여세요.","Tak otevřete okno."],["그러면 혼자 먹고 올게요.","Tak se najím sám a pak přijdu."],["그럼 저는 이제 갈게요.","Tak já už teď půjdu."],["그러면 저 주세요.","V tom případě to dejte mně."]]}};
